+export function accumulateUsage(
+  total: TotalUsage | undefined,
+  roundUsage: UsageMetadata | undefined
+): TotalUsage | undefined {
+  if (!roundUsage) return total;
+  const previous = total ?? {inputTokens: 0, outputTokens: 0, totalTokens: 0};
+  return {
+    inputTokens: previous.inputTokens + roundUsage.inputTokens,
+    outputTokens: previous.outputTokens + roundUsage.outputTokens,
